const contractDropdownOpenByCampaign=new Map();
function contractDropdownSlug(value){
 return String(value||"section").trim().toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,72)||"section";
}
function contractDropdownCampaignKey(state){
 return String(state?.campaignId||state?.saveId||state?.company||"default");
}
function contractDropdownSet(state){
 const key=contractDropdownCampaignKey(state);
 if(!contractDropdownOpenByCampaign.has(key))contractDropdownOpenByCampaign.set(key,new Set());
 return contractDropdownOpenByCampaign.get(key);
}
function contractDropdownKey(d,index){
 const summary=d.querySelector(":scope > summary");
 const label=summary?.querySelector("b")?.textContent||summary?.textContent||("section-"+index);
 const meta=summary?.querySelector("small")?.textContent||"";
 const parent=d.parentElement?.closest("details[data-contract-key]");
 const scope=d.classList.contains("ptm-drop")?"top":d.classList.contains("ptm-subdrop")?"sub":"row";
 return (parent?.dataset.contractKey?parent.dataset.contractKey+"__":"contracts__")+scope+"__"+contractDropdownSlug(label)+"__"+contractDropdownSlug(meta);
}
function captureContractDropdownState(state,root){
 if(!root)return;
 const saved=contractDropdownSet(state);
 root.querySelectorAll("details[data-contract-key]").forEach(d=>{
  if(d.open)saved.add(d.dataset.contractKey);
  else saved.delete(d.dataset.contractKey);
 });
}
function restoreContractDropdownState(state,root){
 if(!root)return;
 const saved=contractDropdownSet(state);
 const used=new Set();
 [...root.querySelectorAll("details")].forEach((d,index)=>{
  let key=contractDropdownKey(d,index),n=1;
  while(used.has(key))key=contractDropdownKey(d,index)+"__"+(++n);
  used.add(key);
  d.dataset.contractKey=key;
  d.open=saved.has(key);
  d.addEventListener("toggle",()=>{
   if(d.open)saved.add(key);
   else saved.delete(key);
  });
 });
}
